import assert from "node:assert/strict";
import { DatabaseSync } from "node:sqlite";
import { writeFileSync, readFileSync } from "node:fs";
import { openDatabase } from "@mizchi/sqlike";
import { buildCatalog, buildDefinedCatalog } from "@mizchi/sqlike/compiler";
import { openAotDatabase } from "@mizchi/sqlike/aot";
import { openDatabase as openFullDatabase } from "@mizchi/sqlike/full";
import { openAotDatabase as openNativeAotDatabase } from "@mizchi/sqlike/aot/native";
import {aotWasm,openPortableCompiled,openAotExecutor,aotExecutorWasm} from "@mizchi/sqlike/aot/core";
import { DefinedDatabase } from "@mizchi/sqlike/defined";
import { exportDefinedSQLite } from "@mizchi/sqlike/defined/sqlite";
import { encodeLtx, applyLtx } from "@mizchi/litestream/ltx";
import { encodeFrame, decodeFrame } from "@mizchi/litestream/protocol";
import { SyncEngine, OfflineClient, statement } from "@mizchi/litestream";
const db = openDatabase();
assert.throws(()=>db.values("SELECT json_array(1)"));
const full=openFullDatabase();assert.deepEqual(full.values("SELECT json_array(1)"),[["[1]"]]);full.close();
const native = new DatabaseSync(":memory:");
const table = "CREATE TABLE t(id INTEGER PRIMARY KEY,r REAL,v TEXT,b BLOB)";
db.run(table); native.exec(table);
const row = [9007199254740993n, 12.5, "\ufeffone\0", new Uint8Array([0,255])];
const sql = "INSERT INTO t VALUES(?,?,?,?) RETURNING id,id,r,v,b";
const reference = native.prepare(sql); reference.setReadBigInts(true); reference.setReturnArrays(true);
assert.deepEqual(db.values(sql,row), reference.all(...row));
assert.throws(() => db.transaction(() => { db.run("DELETE FROM t"); throw Error("rollback"); }), /rollback/);
assert.equal(openDatabase(db.dump()).all("SELECT count(*) AS n FROM t")[0].n, 1n);
db.close(); native.close();
const program = buildCatalog({schema:[table],queries:[{name:"add",sql:"INSERT INTO t VALUES(?,?,?,?) RETURNING id"},{name:"get",sql:"SELECT id,r,v,b FROM t WHERE id=?"}]}).artifact;
const nativeAot=openNativeAotDatabase(program);nativeAot.execute("add",row);assert.deepEqual(nativeAot.prepare("get").get([row[0]]),row);nativeAot.close();
const {instance}=await WebAssembly.instantiate(readFileSync(new URL(import.meta.resolve("@mizchi/sqlike/wasm/aot.wasm"))),{},{builtins:["js-string"],importedStringConstants:"_"});
const wasmAot=openPortableCompiled(aotWasm(instance.exports),program);wasmAot.execute("add",row);assert.deepEqual(wasmAot.prepare("get").get([row[0]]),row);wasmAot.close();
const executor=openAotExecutor(aotExecutorWasm(instance.exports),program);executor.execute("add",row);assert.deepEqual(executor.execute("get",[row[0]]).rows,[row]);assert.equal('dump' in executor,false);executor.close();
const aot = openAotDatabase(program);
aot.execute("add",row);
const get = aot.prepare("get");assert.deepEqual(get.get([row[0]]),row);
const before = aot.dump();
assert.throws(()=>aot.transaction(()=>{aot.execute("add",[1n,2.5,"undo",null]);throw Error("rollback");}),/rollback/);
assert.deepEqual(get.get([row[0]]),row);aot.restore(before);get.finalize();aot.close();
writeFileSync("native-program.json",program);
const catalog = buildDefinedCatalog({schema:[table],queries:[{name:"add",sql:"INSERT INTO t VALUES(?,?,?,?)"},{name:"get",sql:"SELECT id,r,v,b FROM t"}]}, {sqliteExport:true});
const fixed = await DefinedDatabase.memory(catalog);
await fixed.execute("add",row);
assert.deepEqual(await fixed.prepare("get").get(), row);
const image = await exportDefinedSQLite(catalog,await fixed.snapshot());
await fixed.close();
const file = encodeLtx(new Uint8Array(),image,"1","1").data;
assert.deepEqual(applyLtx(new Uint8Array(),"0",file,3).data,image);
const frame = {kind:1,base:0,opId:crypto.randomUUID(),payload:new Uint8Array([1,2])};
assert.deepEqual(decodeFrame(encodeFrame(frame)),frame);
const authority = openDatabase(), replica = openDatabase();
const engine = new SyncEngine(authority);
const client = new OfflineClient(replica, {push:async bytes=>engine.push(bytes),snapshot:async()=>engine.snapshot()});
await client.sync();
client.execute([statement('INSERT INTO notes(id,title,score) VALUES(?,?,?)',['one','hello',1n])],'sql');
assert.deepEqual(authority.all('SELECT id,title FROM notes'),[]);
await client.sync();
assert.deepEqual(authority.all('SELECT id,title FROM notes'),[{id:'one',title:'hello'}]);
replica.close(); authority.close();
const browserCatalog = buildDefinedCatalog({schema:["CREATE TABLE task(id INTEGER PRIMARY KEY,title TEXT)"],queries:[{name:"add",sql:"INSERT INTO task VALUES(?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title"},{name:"get",sql:"SELECT id,title FROM task ORDER BY id"}]});
writeFileSync("browser-catalog.json", JSON.stringify({schema:[...browserCatalog.schema],statements:[...browserCatalog.statements],manifest:browserCatalog.manifest}));
console.log("packed Node consumer passed");
